guard.command:
ls -R bin | head -50; echo "---"; which ekbasis psql; echo "---"; psql -v ON_ERROR_STOP=1 -At <<'SQL'
SELECT 'relkind/comment: ' || relkind || ' | ' || coalesce(obj_description(oid),'(none)') FROM pg_class WHERE relname = 'audit_log';
SELECT 'fk: ' || conrelid::regclass || ' confdeltype=' || confdeltype FROM pg_constraint WHERE contype='f' AND confrelid = 'audit_log'::regclass;
SELECT 'trigger: ' || tgname || ' ' || pg_get_triggerdef(oid) FROM pg_trigger WHERE tgrelid='audit_log'::regclass AND NOT tgisinternal;
SELECT 'child: ' || inhrelid::regclass FROM pg_inherits WHERE inhparent='audit_log'::regclass;
SELECT 'rows total=' || count(*) || ' older_than_90d=' || count(*) FILTER (WHERE at < now() - interval '90 days') || ' min_at=' || min(at) || ' max_at=' || max(at) FROM audit_log;
SELECT 'maintenance_log exists: ' || (to_regclass('maintenance_log') IS NOT NULL);
SQL

