guard.command:
psql -v ON_ERROR_STOP=1 <<'SQL'
\echo '--- relkind/comment for customers, maintenance_log'
SELECT relname, relkind, obj_description(oid) FROM pg_class WHERE relname IN ('customers','maintenance_log');
\echo '--- FKs referencing customers'
SELECT conrelid::regclass AS tbl, confdeltype, conname FROM pg_constraint WHERE contype='f' AND confrelid='customers'::regclass;
\echo '--- triggers on customers'
SELECT tgname, pg_get_triggerdef(oid) FROM pg_trigger WHERE tgrelid='customers'::regclass AND NOT tgisinternal;
\echo '--- inheritance children'
SELECT inhrelid::regclass FROM pg_inherits WHERE inhparent='customers'::regclass;
\echo '--- columns of customers'
SELECT column_name, data_type, is_nullable FROM information_schema.columns WHERE table_name='customers' ORDER BY ordinal_position;
\echo '--- plan distribution'
SELECT plan, count(*) FILTER (WHERE plan_expires_at IS NULL) AS null_expiry, count(*) FILTER (WHERE plan_expires_at < now()) AS expired, count(*) AS total FROM customers GROUP BY plan ORDER BY plan;
\echo '--- rows the step-2 UPDATE would touch'
SELECT count(*) AS rows_to_change, string_agg(DISTINCT plan, ',') AS from_plans, min(plan_expires_at), max(plan_expires_at) FROM customers WHERE plan <> 'free' AND plan_expires_at < now();
\echo '--- sample of affected rows'
SELECT * FROM customers WHERE plan <> 'free' AND plan_expires_at < now() LIMIT 20;
SQL

